@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Get the vertices and partition them into two sets
    Collection<V> vertices = target.getVertices();
    List<Set<V>> partitionedVertices = new ArrayList<>(2);
    for (int i = 0; i < 2; i++) {
        partitionedVertices.add(new HashSet<>());
    }
    int index = 0;
    for (V vertex : vertices) {
        partitionedVertices.get(index).add(vertex);
        index = 1 - index;
    }

    // Add edges between all vertices in the two sets
    Set<V> set1 = partitionedVertices.get(0);
    Set<V> set2 = partitionedVertices.get(1);
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(null, v1, v2);
        }
    }
}

