 * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
 * @return the size of the message
 */
public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.computeSize(message);
    ByteString data = schema.toByteString(message);
    out.write(CodedOutputStream.computeRawVarint32Size(size));
    CodedOutputStream.writeRawVarint32(size, buffer);
    out.write(data.toByteArray());
    return size;
}

/**
 * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
 * @return the size of the message
 */
public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int dataLength = data.length;
    out.write(dataLength >>> 24);
    out.write((dataLength >>> 16) & 0xFF);
    out.write((dataLength >>> 8) & 0xFF);
    out.write(dataLength & 0xFF);
    out.write(data, 0, dataLength);
    return dataLength + 4;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.encode(message, buffer);
    int size = data.length;
    out.write(size >>> 24);
    out.write(size >>> 16);
    out.write(size >>> 8);
    out.write(size);
    out.write(data);
    buffer.clear();
    return size;
}

