    while (start < end) {
        long nextStart = start + fetchDataDuration;
        if (nextStart > end) {
            nextStart = end;
        }
        timeRanges.add(new TimeRange(start, nextStart));
        start = nextStart;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long startTime = start;
        while (startTime < end) {
            long currentTime = startTime + FETCH_DATA_DURATION;
            if (currentTime > end) {
                currentTime = end;
            }
            timeRanges.add(new TimeRange(startTime, currentTime));
            startTime = currentTime;
        }
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    final long FETCH_DATA_DURATION = 3600000; // 1 hour in milliseconds
    long currentStart = start;

    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;

    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long chunkSize = duration / (FETCH_DATA_DURATION / TimeRange.resolution);
        for (long i = 0; i < duration; i += chunkSize) {
            long chunkStart = start + i;
            long chunkEnd = Math.min(chunkStart + chunkSize, end);
            timeRanges.add(new TimeRange(chunkStart, chunkEnd));
        }
    }

    return timeRanges;
}

