public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        if (str == null) {
            return lb;
        }

        int length = str.length();
        if (length > lb.getRemaining()) {
            lb = session.handle(lb);
        }

        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                lb.put((byte) c);
            } else if (c <= 0x7FF) {
                lb.put((byte) (0xC0 | (c >> 6)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            } else {
                lb.put((byte) (0xE0 | (c >> 12)));
                lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.put((byte) (0x80 | (c & 0x3F)));
            }
        }

        return lb;
    } catch (Exception e) {
        return session.handle(lb);
    }
}

