    if (desiredCapacity < 2) return 2;
    int prime = desiredCapacity;
    boolean found = false;
    while (!found) {
        found = isPrime(prime);
        if (!found) {
            prime++;
            if (desiredCapacity >= 1000 && prime - desiredCapacity > desiredCapacity * 0.11) {
                prime = desiredCapacity + (int) (desiredCapacity * 0.11);
            }
        }
    }
    return prime;
}

