public static Type resolveBound(TypeVariable<?> typeVariable) {
    AnnotationMirror[] annotations = typeVariable.getAnnotations();
    for (AnnotationMirror annotation : annotations) {
        if (annotation.getAnnotationType().toString().equals("java.lang.TypeVariable")) {
            Map<? extends ExecutableElement, ? extends AnnotationValue> elementValues = annotation.getElementValues();
            for (Map.Entry<? extends ExecutableElement, ? extends AnnotationValue> entry : elementValues.entrySet()) {
                if (entry.getKey().toString().equals("bound")) {
                    Type bound = (Type) entry.getValue().getValue();
                    return bound;
                }
            }
        }
    }
    return Unknown.class;
}

